def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        # Ensure we have an integer number of nanoseconds
        nanoseconds = int(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be an integer or convertible to int") from exc

    # Constants
    NANOS_PER_SECOND = 1_000_000_000
    SECONDS_PER_MINUTE = 60
    MINUTES_PER_HOUR = 60
    HOURS_PER_DAY = 24
    NANOS_PER_DAY = HOURS_PER_DAY * MINUTES_PER_HOUR * SECONDS_PER_MINUTE * NANOS_PER_SECOND

    if nanoseconds < 0 or nanoseconds > NANOS_PER_DAY:
        raise ValueError(f"nanoseconds must represent a value from 0 to {NANOS_PER_DAY} inclusive, got {nanoseconds}")

    # Decompose nanoseconds into time components
    total_seconds, nano_remainder = divmod(nanoseconds, NANOS_PER_SECOND)
    total_minutes, second = divmod(total_seconds, SECONDS_PER_MINUTE)
    hour, minute = divmod(total_minutes, MINUTES_PER_HOUR)
    microsecond = nano_remainder // 1000  # floor to microseconds

    # Resolve timezone information
    tzinfo = None
    # Accept a tzinfo instance or the string 'UTC'
    if tz is not None:
        try:
            import datetime
            if hasattr(datetime, 'tzinfo') and isinstance(tz, datetime.tzinfo):
                tzinfo = tz
            elif isinstance(tz, str):
                if tz.upper() == 'UTC':
                    tzinfo = datetime.timezone.utc
                else:
                    raise ValueError
            else:
                raise ValueError
        except Exception:
            raise ValueError("tz must be a datetime.tzinfo instance or 'UTC' string")

    # Construct the time object
    try:
        import datetime
        return datetime.time(hour=hour, minute=minute, second=second,
                             microsecond=microsecond, tzinfo=tzinfo)
    except Exception as exc:
        raise RuntimeError("Failed to create time object") from exc

