    if keyword_pos is not None:
        # Grab substring after the keyword
        sub_text = text[keyword_pos + kw_len:].strip()
        # Look for an integer in the remaining text
        m_suppl = re.search(r'(\d+)', sub_text)
        if m_suppl:
            try:
                suppl = int(m_suppl.group(1))
            except ValueError:
                suppl = None
        else:
            # If no number follows the keyword, check if keyword itself is numeric (e.g., 's2')
            m_kw_num = re.search(r'(\d+)', kw)
            if m_kw_num:
                try:
