    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root
    inventory so that we can also check them when validating the content.

    `version_dirs` is an array of version directory names and is assumed to
    be in version sequence (1, 2, 3...).

    The inventory file is expected to be named ``inventory`` inside each
    directory and contain lines formatted as ``path|digest``.  The root
    inventory must already be present in ``self.root_inventory`` as a dict
    mapping paths to their expected digests.  Any path missing from a
    version inventory or any digest that differs from the root inventory
    is recorded in ``self.differing_digests``.  Raises ``ValueError`` when
    a specified inventory file cannot be found or when a path is missing
    from the root inventory.
    """
    if not hasattr(self, "root_inventory"):
        raise ValueError("Root inventory not available in instance")

    # Ensure differing digests dict exists
    if not hasattr(self, "differing_digests"):
        self.differing_digests = {}

    root_inv = self.root_inventory

    for vdir in version_dirs:
        inv_path = f"{vdir}/inventory"
        try:
            with open(inv_path, "r", encoding="utf-8") as fp:
                lines = fp.readlines()
        except FileNotFoundError:
            raise ValueError(f"Inventory file missing for version directory: {vdir}")

        inv_map = {}
        for lineno, line in enumerate(lines, start=1):
            line = line.strip()
            if not line:
