                continue
            parts = line.split("|", 1)
            if len(parts) != 2:
                continue
            path, digest = parts[0].strip(), parts[1].strip()
            inv_map[path] = digest

        # Validate each inventory entry against the root inventory
        for path, cur_digest in inv_map.items():
            if path not in root_inv:
                raise ValueError(f"Path '{path}' in inventory {vdir} not found in root inventory")

            root_digest = root_inv[path]
            if cur_digest != root_digest:
                if path not in self.differing_digests:
                    self.differing_digests[path] = {}
                # Store the differing digest per version directory
                self.differing_digests[path][vdir] = cur_digest

