        if not os.path.exists(path):
            return f"path does not exist: {path}"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # Look for a Namaste file whose name starts with "0="
            namaste_file = None
            for entry in os.listdir(path):
                if entry.startswith("0="):
                    namaste_file = os.path.join(path, entry)
                    break

            if not namaste_file:
                return "no Namaste file present; not an OCFL structure"

            # Try to read the Namaste file
            try:
                with open(namaste_file, "r", encoding="utf-8") as f:
                    content = f.read().lower()
            except Exception as e:
                return f"error reading Namaste file: {e}"

            # Determine type from content if possible
            if "ocfl-root" in content or "root" in content:
                return "root"

            if "ocfl-object" in content or "object" in content:
                return "object"

            # Fallback: if the directory contains an 'objects' subdirectory, it's a root
            if os.path.isdir(os.path.join(path, "objects")):
                return "root"

            # If the directory contains a 'metadata' or a 'versions' subdirectory, treat as object
            for sub in ("metadata", "versions", "obj"):
                if os.path.isdir(os.path.join(path, sub)):
                    return "object"

            # If we have a Namaste file but can't determine specific type, assume object
            return "object"

        # If it's neither file nor directory (e.g., socket, FIFO)
        return f"unsupported file type: {os.path.realpath(path)}"

    except Exception as exc:
        return f"unexpected error while determining path type: {exc}"

