def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError(f"size must be a string, got {type(size).__name__}")
    s = size.strip()
    if not s:
        raise ValueError("size string is empty")

    # Find where the numeric part ends
    num_end = 0
    for i, ch in enumerate(s):
        if ch.isdigit() or ch == '.':
            num_end = i + 1
        else:
            break

    num_part = s[:num_end]
    unit_part = s[num_end:].strip()

    if not num_part:
        raise ValueError("numeric part missing in size string")

    try:
        number = float(num_part)
    except ValueError as e:
        raise ValueError(f"invalid numeric value '{num_part}'") from e

    # If there is no unit, assume bytes
    if not unit_part:
        return int(round(number))

    # Determine multiplier based on first letter of unit part
    unit_char = unit_part[0].lower()
    multipliers = {
        'k': 10**3,
        'm': 10**6,
        'g': 10**9,
        't': 10**12,
        'p': 10**15,
        'e': 10**18,
    }
    if unit_char not in multipliers:
        raise ValueError(f"unknown unit '{unit_part}'")
    return int(round(number * multipliers[unit_char]))

