def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import re
    import logging

    def _replace_env(values):
        """Recursively replace ${VAR} placeholders in string values using os.environ."""
        try:
            import os
        except Exception:
            return values
        if isinstance(values, dict):
            return {k: _replace_env(v) for k, v in values.items()}
        if isinstance(values, list):
            return [_replace_env(v) for v in values]
        if isinstance(values, str):
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), match.group(0))
            return pattern.sub(repl, values)
        return values

    configurations = {}
    error_records = []

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            try:
                parsed = json.loads(raw)
            except json.JSONDecodeError as e:
                raise ValueError(f'JSON parsing failed for {fname}: {e}')

            if not isinstance(parsed, dict):
                raise ValueError(f'Top-level object in {fname} is not a JSON object')

            if overrides:
                if not isinstance(overrides, dict):
                    raise ValueError('Overrides must be a dictionary')
                parsed.update(overrides)

            if resolve_env:
                parsed = _replace_env(parsed)

            configurations[fname] = parsed
        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return configurations, error_records

