def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the metaclass for a new type, given its bases and an
    optional explicit metaclass argument.  The algorithm follows the
    semantics of CPython: if an explicit metaclass is supplied, all
    bases must be compatible with it; otherwise find the most derived
    metaclass that is compatible with all bases.  Incompatible bases
    raise a TypeError.
    """
    # Basic validation
    try:
        base_list = tuple(bases)
    except TypeError as exc:
        raise TypeError("bases must be an iterable of types") from exc

    # Compute metaclasses of the bases
    base_metas = []
    for b in base_list:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a type")
        base_metas.append(type(b))

    # If an explicit metaclass is given, validate compatibility
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a type")
        for b, m in zip(base_list, base_metas):
            if not issubclass(m, explicit_mc):
                raise TypeError(
                    f"explicit metaclass {explicit_mc.__name__!r} is not a supertype "
                    f"of {b.__name__!r}'s metaclass {m.__name__!r}")
        return explicit_mc

    # No explicit metaclass – compute the most derived common metaclass
    # Start with the metaclass of the first base, or `type` if no bases.
    if not base_metas:
        return type

    selected_meta = base_metas[0]
    for m in base_metas[1:]:
        if issubclass(m, selected_meta):
            selected_meta = m
        elif not issubclass(selected_meta, m):
            # Conflict: neither metaclass is a subclass of the other
            raise TypeError(
                f"metaclass conflict: {selected_meta.__name__!r} and {m.__name__!r} are not compatible")
    return selected_meta

