    import json
    import os

    # Validate playbook path
    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Build base command
    cmd = ["ansible-playbook"]

    # Add ansible_args
    if ansible_args:
        for key, value in ansible_args.items():
            if not key.startswith("--"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
            elif value is None:
                # Skip keys with None value
                continue
            else:
                cmd.extend([key, str(value)])

    # Add verbosity
    if verbose:
        if isinstance(verbose, int) and 1 <= verbose <= 4:
            cmd.append("-" + "v" * verbose)
        else:
            # If passed as string, use directly
            cmd.append(str(verbose))

    # Add playbook path
    cmd.append(playbook_path)

    # Add extra vars
    if extra_vars:
        try:
            json_vars = json.dumps(extra_vars, ensure_ascii=False)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid extra_vars, must be JSON serializable: {exc}")
        cmd.extend(["--extra-vars", json_vars])

    # Log the command if plugin provides logging
    try:
        ir_plugin.log_debug(f"Running command: {' '.join(cmd)}")
    except Exception:
        pass  # ignore if logging not available

    # Execute
    try:
        result = subprocess.run(
            cmd,
            text=True,
            capture_output=True,
            check=False,  # do not raise on non-zero exit so caller can inspect
        )
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"ansible-playbook command not found: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

